    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_event_kind(self.kind, serializer);
    sse_encode_String(self.text, serializer);
    sse_encode_String(self.detail, serializer);
    sse_encode_bool(self.canRemember, serializer);
    sse_encode_i_64(self.x, serializer);
    sse_encode_i_64(self.y, serializer);
    sse_encode_bool(self.visible, serializer);
    sse_encode_list_monitor(self.monitors, serializer);
    sse_encode_u_32(self.activeMonitor, serializer);
    sse_encode_opt_box_autoadd_access(self.access, serializer);
    sse_encode_opt_box_autoadd_stats(self.stats, serializer);
    sse_encode_u_32(self.id, serializer);
    sse_encode_list_prim_u_8_strict(self.bytes, serializer);
    sse_encode_list_dir_item(self.entries, serializer);
    sse_encode_bool(self.ok, serializer);
    sse_encode_bool(self.cursorSupported, serializer);
    sse_encode_bool(self.scalingSupported, serializer);
  }

  @protected
  void sse_encode_session_options(
    SessionOptions self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.maxWidth, serializer);
    sse_encode_u_32(self.maxHeight, serializer);
    sse_encode_bool(self.video, serializer);
  }

  @protected
  void sse_encode_stats(Stats self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.rttMs, serializer);
    sse_encode_f_32(self.fps, serializer);
    sse_encode_f_32(self.kbps, serializer);
    sse_encode_String(self.route, serializer);
  }

  @protected
  void sse_encode_target(Target self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.name, serializer);
    sse_encode_String(self.hostId, serializer);
    sse_encode_opt_box_autoadd_i_64(self.machineId, serializer);
    sse_encode_list_String(self.addrs, serializer);
  }

  @protected
  void sse_encode_u_16(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint16(self);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_update(Update self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.version, serializer);
    sse_encode_i_64(self.size, serializer);
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

